import{_ as r,I as i,c as n,o,ag as a,J as s}from"./chunks/framework.Vyheyqg9.js";const g=JSON.parse('{"title":"RAG: ingestion to supported answers","description":"","frontmatter":{},"headers":[],"relativePath":"applied-ai/rag/index.md","filePath":"applied-ai/rag/index.md"}'),d={name:"applied-ai/rag/index.md"};function l(c,e,p,h,u,m){const t=i("MermaidDiagram");return o(),n("div",null,[e[0]||(e[0]=a('<h1 id="rag-ingestion-to-supported-answers" tabindex="-1">RAG: ingestion to supported answers <a class="header-anchor" href="#rag-ingestion-to-supported-answers" aria-label="Permalink to “RAG: ingestion to supported answers”">​</a></h1><p>Retrieval-augmented generation selects external evidence for a generation request. It does not change model weights or establish that a retrieved statement is true. The application must preserve current access, provenance, failure categories and evidence sufficiency throughout.</p><h2 id="reading-and-implementation-order" tabindex="-1"><span class="hub-section-number">1 </span>Reading and implementation order <a class="header-anchor" href="#reading-and-implementation-order" aria-label="Permalink to “1 Reading and implementation order”">​</a></h2><ul><li><a href="./../../python-for-ai/document-processing.html">Extraction and chunk provenance</a>: bounded text/CSV first; complex formats need separate isolation/fidelity decisions.</li><li><a href="./../../python-for-ai/embeddings-and-similarity.html">Embeddings, lexical and hybrid retrieval</a>: exact identifiers versus paraphrases, compatible spaces, filters before top-k, separately observable branch rankings.</li><li><a href="./../../python-for-ai/vector-storage-lifecycle.html">Persistent index/data lifecycle</a>: current sources/ACLs, source versions, staged index generation and update/delete. Learn this before composing the full query pipeline.</li><li><a href="./../../python-for-ai/retrieval-context.html">Evidence/citations</a>: resolve exact current spans; mechanical membership does not prove entailment.</li><li><a href="./../../python-for-ai/retrieval-pipeline.html">Retrieval/reranking/context</a>: original query retained, bounded union, rerank only permitted text, final request budgeting.</li><li><a href="./answering-and-failures.html">Answering boundary</a>: compose generation, publication and recovery without hiding missing adapters.</li><li><a href="./../../python-for-ai/evaluation-lab.html">Evaluation</a>, <a href="./../../python-for-ai/retrieval-debugging.html">debugging/freshness</a>, <a href="./../../python-for-ai/provider-data-lifecycle.html">derivative lifecycle</a>: labeled relevance/support, oracle diagnostics and deletion reconciliation.</li></ul><h2 id="two-paths-with-different-owners" tabindex="-1"><span class="hub-section-number">2 </span>Two paths with different owners <a class="header-anchor" href="#two-paths-with-different-owners" aria-label="Permalink to “2 Two paths with different owners”">​</a></h2>',5)),s(t,{"encoded-source":"flowchart%20TD%0A%20%20%20%20Bytes%5BAuthorized%20source%20bytes%5D%20--%3E%20Parse%5BParse%20and%20retain%20provenance%5D%0A%20%20%20%20Parse%20--%3E%20Chunk%5BVersioned%20chunk%20metadata%5D%0A%20%20%20%20Chunk%20--%3E%20Index%5BCompatible%20index%20generation%5D%0A%20%20%20%20Question%5BOriginal%20question%20and%20authenticated%20scope%5D%20--%3E%20Retrieve%5BFiltered%20lexical%20or%20hybrid%20candidates%5D%0A%20%20%20%20Index%20--%3E%20Retrieve%0A%20%20%20%20Retrieve%20--%3E%20Resolve%5BCurrent%20source%20and%20exact%20span%20checks%5D%0A%20%20%20%20Resolve%20--%3E%20Rank%5BBounded%20rerank%20and%20context%20selection%5D%0A%20%20%20%20Rank%20--%3E%20Budget%5BCount%20final%20payload%20and%20reserve%20output%5D%0A%20%20%20%20Budget%20--%3E%20Generate%5BProposed%20answer%5D%0A%20%20%20%20Generate%20--%3E%20Validate%5BSchema%20citations%20and%20claim%20support%5D%0A%20%20%20%20Validate%20--%3E%20Publish%5BSafe%20display%20and%20authorized%20citation%20open%5D"}),e[1]||(e[1]=a('<p>Ingestion metadata binds tenant/logical source, immutable bytes/version, extraction/chunk policy, locator/span, embedding-space identity and index generation. Query scope comes from authentication, never a generated rewrite. Changes in any representation policy require a deliberate migration; equal vector dimensions alone do not make spaces compatible.</p><h2 id="when-simpler-retrieval-is-sufficient" tabindex="-1"><span class="hub-section-number">3 </span>When simpler retrieval is sufficient <a class="header-anchor" href="#when-simpler-retrieval-is-sufficient" aria-label="Permalink to “3 When simpler retrieval is sufficient”">​</a></h2><table tabindex="0"><thead><tr><th>Need</th><th>Prefer first</th><th>Add complexity only if evidence justifies it</th></tr></thead><tbody><tr><td>Exact known record/aggregate</td><td>Authorized parameterized database query</td><td>A model is unnecessary for a deterministic field</td></tr><tr><td>Error codes, names, exact phrases</td><td>Lexical lookup/full-text search</td><td>Semantic similarity can miss a critical identifier/negation</td></tr><tr><td>Small authorized source set</td><td>Direct search or bounded context</td><td>Count real payload and evaluate omissions before adding a vector service</td></tr><tr><td>Paraphrases across a growing corpus</td><td>Compare semantic and lexical baselines</td><td>Add hybrid/ANN/reranking after labeled recall/support and operational checks</td></tr></tbody></table><p>The runnable lexical scorer is Jaccard overlap, not BM25. Hand-authored vectors demonstrate geometry/access order, not learned semantic quality. Rank fusion is not raw score addition. A reranker cannot recover evidence absent from candidates; a nonempty ranking is not proof that an answer exists.</p><p><a href="./../../practice/applied-ai/rag-assistant.html">Practice: staged P-334</a> · <a href="./../../workbench/applied-ai/python/">Workbench and limits</a></p>',5))])}const b=r(d,[["render",l]]);export{g as __pageData,b as default};
